#!/usr/bin/env python3
"""Hash-check and synthesize the completed Lean/SAM2 experiment evidence."""
import argparse,json,sys
from pathlib import Path
ROOT=Path(__file__).resolve().parents[1];sys.path.insert(0,str(ROOT))
from scripts.memory_token_io import digest,validate_output
p=argparse.ArgumentParser();p.add_argument('--experiments',type=Path,required=True);p.add_argument('--output',type=Path,required=True);a=p.parse_args();read=lambda f:json.loads(f.read_text())
paths={'cohort':'lean_auto_multiscale_v1/cohort_combined_attempt01','priority':'lean_priority_decision_v1/report_attempt01','same_read':'lean_same_read_fusion_priority_v1/four_sequence_report_attempt01','usage':'lean_historical_usage_capture_v1/group_control_report_attempt02','channel':'lean_utility_trained_channel_pilot_v1/audit_attempt02','source_channel':'lean_source_utility_channel_loso_v1/audit_attempt02','prompt':'lean_priority_prompt_quality_v1/audit_attempt01','oracle':'lean_fixed_box_oracle_diagnostic_v1/audit_attempt01'};data={};provenance={}
for name,rel in paths.items():
 folder=a.experiments/rel;done=read(folder/'completion.json');result=folder/'results.json'
 if not done['passed'] or done['results_sha256']!=digest(result):raise ValueError(f'{name} results changed')
 report=folder/'report.md'
 if 'report_sha256' in done and done['report_sha256']!=digest(report):raise ValueError(f'{name} report changed')
 data[name]=read(result);provenance[name]={'results':str(result),'results_sha256':digest(result),'completion_sha256':digest(folder/'completion.json'),'report':str(report),'report_sha256':digest(report)}
uv=read(a.experiments/'lean_historical_usage_capture_v1/group_control_verification_attempt01/verification.json')
if not uv['passed'] or uv['report_sha256']!=digest(a.experiments/paths['usage']/'results.json') or uv['verifier_sha256']!=digest(ROOT/'scripts/verify_lean_historical_usage_report.py'):raise ValueError('Historical usage independent verification changed')
cohort=data['cohort'];rows=data['priority']['rows'];reads=data['same_read']['rows'];usage={r['sequence']:r for r in data['usage']['rows']};folds={r['sequence']:r for r in data['source_channel']['rows']}
if len(rows)!=4 or {r['sequence'] for r in rows}!={'seq8','seq11','seq20','seq23'} or {r['sequence'] for r in reads}!={'seq8','seq11','seq20','seq23'} or len(cohort['sequences'])!=21:raise ValueError('Evidence coverage differs')
out=validate_output(a.output);out.mkdir(parents=True,exist_ok=False);summary={'priority':rows,'same_read':reads,'source_utility_loso':data['source_channel']['rows'],'historical_usage':data['usage']['rows'],'cohort_scope':cohort['scope'],'sources':provenance,'usage_verification_sha256':digest(a.experiments/'lean_historical_usage_capture_v1/group_control_verification_attempt01/verification.json'),'runner_sha256':digest(Path(__file__))};(out/'results.json').write_text(json.dumps(summary,indent=2)+'\n')
lines=['# PolypGen Lean/SAM2 experiment evidence','','## Automatic priority-video comparisons','','The automatic runs within each comparison use the same one-time YOLO-derived initialization and same scoring frame IDs. Present Dice uses matched labeled-present targets; false alarms cover all labeled-empty frames. Seq23 is cropped to the fixed inset-excluded main viewport. Fused and raw-two have equal read counts but different state histories; recent and spread have matched represented-token budgets, but not the same memory contents.','','| Sequence | Initial label | Fused Dice | Raw-two Dice | Recent Dice | Spread Dice | Empty FAs: recent / spread |','|---|---|---:|---:|---:|---:|---:|']
for r in rows:lines.append(f"| {r['sequence']} | {'present' if r['first_label_present'] else 'empty'} | {r['fused_dice']:.3f} | {r['raw_two_dice']:.3f} | {r['raw_window_dice']:.3f} | {r['spread_dice']:.3f} | {r['raw_window_empty_false_alarms']} / {r['spread_empty_false_alarms']} ({r['empty_frames']}) |")
lines+=['','The initial masks on seq20 and seq23 were nonempty on labeled-empty frames; seq11 started with an overextended mask. Empty annotations may be incomplete. All four videos were previously inspected, and these observations do not establish the cause of later failure.','','## Historical 21-sequence references','','These older numbers share historical target-frame IDs but **not** automatic prompts: native SAM2 and Lean start from ground-truth masks, while the combined system uses YOLO and its own mask. The older automatic cohort predates the seq23 inset exclusion and later CPU RoPE correction; do not treat it as the corrected four-sequence comparison or an independent benchmark.','','| Historical system | Initial prompt | Equal-sequence present Dice | Empty FAs |','|---|---|---:|---:|',f"| Native SAM2 | GT mask | {cohort['historical_native_dice']:.4f} | {cohort['historical_native_false_alarms']} / {cohort['historical_matched_empty']} |",f"| Lean-SAM2 | GT mask | {cohort['historical_lean_dice']:.4f} | {cohort['historical_lean_false_alarms']} / {cohort['historical_matched_empty']} |",f"| Automatic Lean + early prompt + multi-scale anchor | YOLO + predicted mask | {cohort['automatic_combined_historical_dice']:.4f} | {cohort['automatic_combined_historical_false_alarms']} / {cohort['historical_matched_empty']} |",'','## Controlled diagnostics and decision','']
max_delta=max(abs(r['dice_difference']) for r in reads if r['present']);lines.append(f"- Same-read raw-versus-fused replacement was checked on {len(reads)} selected reads across the four priority sequences. Largest absolute labeled-present Dice change was {max_delta:.6f}; the substitution does not model subsequent propagation. At seq23 frame 35, 86,739 pixels changed while both masks had zero annotated overlap.")
lines.append('- Prompt quality and saved-box versus GT-derived oracle-box studies were evaluated separately. Oracle boxes are unavailable at inference and are not guaranteed upper bounds. The existing one-shot schedule cannot recover a missed initialization without changing the prohibited redetection/gating constraint.')
lines.append(f"- The TCMN-author channel gate was trained both on foreground occupancy and on conditional source/group-deletion utility. In leave-one-sequence-out source tests, seq9 ranking concordance was {folds['seq9']['concordance']['utility_trained']:.3f} for the gate versus {usage['seq9']['rank_concordance']['historical_usage']:.3f} for causal historical Lean usage and {usage['seq9']['rank_concordance']['rgb']:.3f} for RGB, over four present reads. Seq10 has only one present evaluation read. Shuffled and distributed random controls are in the source reports.")
lines.append('- No channel candidate showed sufficiently reliable matched-read benefit to justify propagation. The research checkpoints remain non-inference artifacts. Existing raw/fused and recent/spread full-video results are reported above, but do not establish that a learned gate improves video Dice or empty-frame behavior.')
lines+=['','## Interpretation and scope','','The feature-token budget does not measure total RAM or latency. Full-video comparisons are retrospective and contain different evolving memories; same-read tests are conditional local interventions. The cohort and evaluation sequences were previously inspected, original detector training exposure and patient independence are unknown, and one eligible empty read in the utility-score study cannot support a false-alarm conclusion. The existing multi-scale anchor blends pooled context from one memory grid and is CMSA-inspired, not CMSA-Net’s trained multi-stage CMA module. No new redetection or confidence gate was introduced.','','Detailed results and machine-readable source hashes are in results.json. Source reports:','', '- [Four-sequence automatic comparison and prompt analysis](../../lean_priority_decision_v1/report_attempt01/report.md)', '- [Same-read raw/fused effects on priority reads](../../lean_same_read_fusion_priority_v1/four_sequence_report_attempt01/report.md)', '- [Historical usage and matched controls](../../lean_historical_usage_capture_v1/group_control_report_attempt02/report.md)', '- [Utility-trained channel gate and source-sequence folds](../../lean_source_utility_channel_loso_v1/audit_attempt02/report.md)', '- [Historical 21-sequence cohort](../../lean_auto_multiscale_v1/cohort_combined_attempt01/report.md)']
(out/'report.md').write_text('\n'.join(lines)+'\n');(out/'completion.json').write_text(json.dumps({'passed':True,'results_sha256':digest(out/'results.json'),'report_sha256':digest(out/'report.md')},indent=2)+'\n');print('\n'.join(lines))
